// WinAnsi (cp1252) repertoire check — jsPDF standard fonts.
const WINANSI_EXTRA = new Set([
  0x20ac, 0x201a, 0x0192, 0x201e, 0x2026, 0x2020, 0x2021, 0x02c6, 0x2030,
  0x0160, 0x2039, 0x0152, 0x017d, 0x2018, 0x2019, 0x201c, 0x201d, 0x2022,
  0x2013, 0x2014, 0x02dc, 0x2122, 0x0161, 0x203a, 0x0153, 0x017e, 0x0178,
]);
function isWinAnsiSafe(value) {
  for (const ch of value) {
    const cp = ch.codePointAt(0);
    if (cp >= 0x20 && cp <= 0x7e) continue;
    if (cp >= 0xa0 && cp <= 0xff) continue;
    if (WINANSI_EXTRA.has(cp)) continue;
    return false;
  }
  return true;
}

const baseOf = (language) => String(language || 'en').split('-')[0];

/**
 * The label set for a business language: the locale's own strings
 * where they exist AND can render in the PDF fonts, English
 * everywhere else (per string, never whole-document).
 */
export function printLabelsFor(language) {
  const row = LABELS[baseOf(language)] || LABELS.en;
  const out = {};
  for (const key of Object.keys(LABELS.en)) {
    const candidate = row[key] || LABELS.en[key];
    out[key] = isWinAnsiSafe(candidate) ? candidate : LABELS.en[key];
  }
  return out;
}

/** Fill {name}-style placeholders in a label string. */
export function fillLabel(template, values) {
  return String(template).replace(/\{(\w+)\}/g, (match, name) =>
    values && values[name] != null ? String(values[name]) : match,
  );
}

export const PRINT_LABEL_KEYS = Object.keys(LABELS.en);
export const PRINT_LABEL_LOCALES = Object.keys(LABELS);

